import java.util.Scanner;

public class Main {
    static long n;
    static int answer;
    static long[] digits = new long[17];

    static int compute(long x) {
        int steps, current = 16;
        if (x <= 11) return (int)Math.min(x, 13 - x);
        while (digits[current - 1] >= x) current--;
        steps = (int)((x / digits[current - 1]) * (current - 1) + compute(x % digits[current - 1]));
        if (x < digits[current] - x) return steps;
        return Math.min(steps, current + compute(digits[current] - x));
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        digits[1] = 1;
        for (int i = 2; i <= 16; ++i) {
            digits[i] = digits[i - 1] * 10 + 1;
        }
        n = sc.nextLong();
        System.out.println(compute(n));
        sc.close();
    }
}
